using System;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Windows.Forms;namespace ServiceTool{static class NetButtonStateTest{static IEnumerable<Control> Walk(Control p){foreach(Control c in p.Controls){yield return c;foreach(var n in Walk(c))yield return n;}}[STAThread]static int Main(){Application.EnableVisualStyles();try{using(var f=new DotNetUpdatesForm(()=>null)){f.Show();Application.DoEvents();var grid=Walk(f).OfType<ServiceGrid>().Single();if(!grid.TouchScrollingEnabled)throw new Exception("Touch disabled");var flags=BindingFlags.NonPublic|BindingFlags.Instance;var list=(List<DotNetUpdate>)typeof(DotNetUpdatesForm).GetField("updates",flags).GetValue(f);var saved=(HashSet<string>)typeof(DotNetUpdatesForm).GetField("saved",flags).GetValue(f);var all=(Button)typeof(DotNetUpdatesForm).GetField("all",flags).GetValue(f);var download=(Button)typeof(DotNetUpdatesForm).GetField("download",flags).GetValue(f);var update=typeof(DotNetUpdatesForm).GetMethod("UpdateButtons",flags);list[0].Version="99.0.0";update.Invoke(f,null);if(all.Text!="Выбрать всё"||!all.Enabled||download.Enabled)throw new Exception("Initial selectable state");grid.Rows[0].Cells[0].Value=true;if(all.Text!="Снять выбор"||!download.Enabled)throw new Exception("Selected state");saved.Add(list[0].Local.Id);grid.Rows[0].Cells[0].Value=false;update.Invoke(f,null);if(all.Text!="Выбрать всё"||all.Enabled||download.Enabled)throw new Exception("Completed state");typeof(DotNetUpdatesForm).GetMethod("ShowCurrent",flags).Invoke(f,new object[]{list.Last()});if(grid.CurrentRow.Index!=list.Count-1)throw new Exception("Current download row not followed");Console.WriteLine("PASS: selection/reset/button availability, follow-current-row, touch enabled. No network or installers.");}return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}